import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZV43BuildingLoaderOracle extends GhidraScript{
static final long P=0x5c5e38L,D=0x1800000L,S=0x7fff0000L,R=0x12345000L,F=R+4096;
long read(EmulatorHelper e,long a,int n){long v=0;byte[]b=e.readMemory(toAddr(a),n);for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format("%02x",v&255));return s.toString();}void resume(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<64;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{int n=new int[]{0,1,17,30,31,35}[s%6];byte[]pool=new byte[35*88],disk=new byte[35*80];for(int i=0;i<pool.length;i++)pool[i]=(byte)(s*17+i*13+19);for(int i=0;i<disk.length;i++)disk[i]=(byte)(s*23+i*29+31);e.writeMemory(toAddr(P),pool);e.writeMemory(toAddr(D),disk);put(e,0x474058,4,F);put(e,0x64d7e4,4,n*80);put(e,S,4,R);e.writeRegister("ESP",S);for(long pc:new long[]{R,F,0x4652d0})e.setBreakpoint(toAddr(pc));if(!e.run(toAddr(0x45fcb0),null,monitor))throw new Exception(e.getLastError());int load=0,free=0;while(e.readRegister("EIP").longValue()!=R){long pc=e.readRegister("EIP").longValue();if(pc==0x4652d0){load++;e.writeRegister("EAX",D);}else if(pc==F){free++;if(read(e,e.readRegister("ESP").longValue()+4,4)!=D)throw new Exception("wrong free");}else throw new Exception("unexpected"+pc);resume(e);}out.println("{\"scenario\":"+s+",\"count\":"+n+",\"loads\":"+load+",\"frees\":"+free+",\"pool\":\""+hex(e.readMemory(toAddr(P),pool.length))+"\"}");}finally{e.dispose();}}}}}